#!/usr/bin/env bash
# Builds and validates the connector's CycloneDX 1.6 SBOM (CONJ-1353):
#   1. mvn package        -> target/bom.json, generated by cyclonedx-maven-plugin and enriched in
#                            place by .github/sbom/enrich.groovy (skipped with SKIP_BUILD=1)
#   2. cyclonedx validate -> CycloneDX 1.6 schema (including SPDX license ids)
#   3. check-sbom.py      -> CISA minimum elements, purl syntax, dependency graph
# Copies the result to target/mariadb-java-client-<version>.cdx.json and prints its path.
set -euo pipefail
cd "$(dirname "$0")/../.."

CYCLONEDX_CLI_VERSION=${CYCLONEDX_CLI_VERSION:-0.33.1}

if [[ -z "${SKIP_BUILD:-}" ]]; then
  mvn -B -q package -DskipTests -Dgpg.skip
fi
version=$(mvn -B -q help:evaluate -Dexpression=project.version -DforceStdout)
out="target/mariadb-java-client-${version}.cdx.json"
cp target/bom.json "$out"

cli=${CYCLONEDX_CLI:-target/cyclonedx-cli}
if [[ ! -x "$cli" ]]; then
  case "$(uname -s)-$(uname -m)" in
    Linux-x86_64) asset=cyclonedx-linux-x64 ;;
    Linux-aarch64) asset=cyclonedx-linux-arm64 ;;
    Darwin-arm64) asset=cyclonedx-osx-arm64 ;;
    Darwin-x86_64) asset=cyclonedx-osx-x64 ;;
    *) echo "no cyclonedx-cli binary for $(uname -s)-$(uname -m); set CYCLONEDX_CLI" >&2; exit 1 ;;
  esac
  curl -fsSL -o "$cli" "https://github.com/CycloneDX/cyclonedx-cli/releases/download/v${CYCLONEDX_CLI_VERSION}/${asset}"
  chmod +x "$cli"
fi
"$cli" validate --input-file "$out" --input-format json --input-version v1_6 --fail-on-errors >&2
python3 .github/sbom/check-sbom.py "$out" >&2

echo "$out"
